# --------------------------------------------------------------------------
# Hesaplama
# --------------------------------------------------------------------------
def _fmt(n) -> str:
    return f"{n:,.0f}".replace(",", ".") + " ₺"


def _pct(d: float) -> str:
    return f"{abs(d):.1f}".replace(".", ",")


def durum(fiyat, tsf, esik: float) -> tuple[str, float]:
    """ok / warn / bad / none ve TSF'ye göre % fark."""
    if fiyat is None:
        return "none", 0.0
    if not tsf:                        # [eklendi] TSF girilmemis: karsilastirma yapilamaz
        return "nt", 0.0
    d = (fiyat - tsf) / tsf * 100
    if d >= -0.001:
        return "ok", d
    if d >= -esik:
        return "warn", d
    return "bad", d


def hesapla(satirlar: list[dict], esik: float = 5) -> dict:
    kanallar = [k["ad"] for k in KANALLAR]
    tot = {"ok": 0, "warn": 0, "bad": 0, "nt": 0, "n": 0, "bb_own": 0, "bb_lost": 0}
    ch = {k: {"ok": 0, "warn": 0, "bad": 0, "nt": 0, "n": 0, "bb_own": 0, "bb_n": 0} for k in kanallar}
    alarmlar, satir_ozet = [], []
    for r in satirlar:
        hucreler, sapma, bb_kayip = [], False, False
        for k in kanallar:
            fiyat = r.get("fiyatlar", {}).get(k)
            bb = r.get("buybox", {}).get(k)
            st_, d = durum(fiyat, r["tsf"], esik)
            if st_ != "none":
                tot[st_] += 1; ch[k][st_] += 1
                if st_ != "nt":                # uyum oranlari sadece karsilastirilabilen listelemelerden
                    tot["n"] += 1; ch[k]["n"] += 1
                if bb is True:
                    tot["bb_own"] += 1; ch[k]["bb_own"] += 1; ch[k]["bb_n"] += 1
                elif bb is False:
                    tot["bb_lost"] += 1; ch[k]["bb_n"] += 1; bb_kayip = True
            if st_ in ("warn", "bad"):
                sapma = True
            if st_ == "bad":
                alarmlar.append({"urun": f'{r.get("marka","")} {r["urun"]}'.strip(), "kanal": k,
                                 "fiyat": fiyat, "tsf": r["tsf"], "d": d})
            hucreler.append({"durum": st_, "fiyat": fiyat, "d": d, "bb": bb,
                             "link": r.get("linkler", {}).get(k)})
        satir_ozet.append({**r, "hucreler": hucreler, "sapma": sapma, "bb_kayip": bb_kayip})
    alarmlar.sort(key=lambda a: a["d"])
    return {"satirlar": satir_ozet, "tot": tot, "kanal": ch, "alarmlar": alarmlar}


