def baslik(esik: float = 5) -> None:
    sol, sag = st.columns([1, 1])
    with sol:
        st.markdown('<div class="pt-title"><h1>Fiyat &amp; Buybox Takibi</h1>'
                    "<p>Pazar yerlerindeki satış fiyatlarının TSF'ye uyumu ve buybox durumu</p></div>",
                    unsafe_allow_html=True)
    with sag:
        e = f"{esik:g}"
        st.markdown(f"""<div class="pt-legend" style="padding-top:22px"><span style="color:#6A7E72">Renk kodu</span>
<span class="pt-chip pt-ok"><span class="pt-dot" style="background:#1F9D57"></span>TSF'ye uygun</span>
<span class="pt-chip pt-warn"><span class="pt-dot" style="background:#E0A800"></span>%0–{e} altında</span>
<span class="pt-chip pt-bad"><span class="pt-dot" style="background:#D2402F"></span>%{e}+ altında</span></div>""",
                    unsafe_allow_html=True)


def kpi_kartlari(h: dict, urun_sayisi: int, esik: float = 5) -> None:
    t = h["tot"]; n = max(t["n"], 1)
    okp = round(t["ok"] / n * 100); wp = round(t["warn"] / n * 100); bp = max(0, 100 - okp - wp)
    bbn = max(t["bb_own"] + t["bb_lost"], 1)
    st.markdown(f"""<div class="pt-kpis">
<div class="pt-card pt-kpi"><span class="lbl">Takip edilen ürün</span>
  <div class="val"><b class="num">{urun_sayisi}</b><span>ürün × {len(KANALLAR)} kanal</span></div>
  <span class="sub">{t["n"] + t["nt"]} aktif listeleme</span></div>
<div class="pt-card pt-kpi"><span class="lbl">TSF uyum oranı</span>
  <div class="val"><b class="num" style="color:#178A4E">%{okp}</b><span>listeleme</span></div>
  <div class="pt-bar"><div style="width:{okp}%;background:#1F9D57"></div><div style="width:{wp}%;background:#E0A800"></div><div style="width:{bp}%;background:#D2402F"></div></div></div>
<div class="pt-card pt-kpi"><span class="lbl">Buybox payı</span>
  <div class="val"><b class="num">%{round(t["bb_own"] / bbn * 100)}</b><span>listeleme</span></div>
  <span class="sub">{t["bb_own"]} kazanılan · {t["bb_lost"]} kaybedilen</span></div>
<div class="pt-card pt-kpi bad"><span class="lbl">Kritik sapma</span>
  <div class="val"><b class="num">{t["bad"]}</b><span>listeleme %{esik:g}+ altında</span></div>
  <span class="sub">{t["warn"]} listeleme sarı bölgede</span></div>
</div>""", unsafe_allow_html=True)


def _hucre(c: dict) -> str:
    ic = _hucre_ic(c)
    link = str(c.get("link") or "")
    if link.startswith("http") and c["durum"] != "none":
        return f'<a class="pt-link" href="{html.escape(link, quote=True)}" target="_blank">{ic}</a>'
    return ic


def _hucre_ic(c: dict) -> str:
    if c["durum"] == "none":
        return '<div class="pt-cell pt-none">Satışta yok<span style="font-size:11px;font-weight:400">Liste dışı</span></div>'
    if c["durum"] == "nt":
        bb = '<span class="bb own">BB</span>' if c["bb"] is True else ('<span class="bb lost">BB</span>' if c["bb"] is False else "")
        return (f'<div class="pt-cell pt-nt"><div class="p"><span class="num">{_fmt(c["fiyat"])}</span></div>'
                f'<div class="d"><span>TSF yok</span>{bb}</div></div>')
    d = c["d"]
    fark = ("+%" + _pct(d) if d > 0.001 else "TSF") if c["durum"] == "ok" else "−%" + _pct(d)
    bb = ""
    if c["bb"] is True:
        bb = '<span class="bb own">BB</span>'
    elif c["bb"] is False:
        bb = '<span class="bb lost">BB</span>'
    return (f'<div class="pt-cell pt-{c["durum"]}"><div class="p">{_IKON[c["durum"]]}'
            f'<span class="num">{_fmt(c["fiyat"])}</span></div>'
            f'<div class="d"><span class="num">{fark}</span>{bb}</div></div>')


def _urun_hucre(r: dict) -> str:
    ad = html.escape(str(r["urun"]))
    alt = " · ".join(html.escape(str(x)) for x in (r.get("marka"), r.get("kategori")) if x)
    ipucu = html.escape(str(r.get("tam_ad") or ""), quote=True)
    g = str(r.get("gorsel") or "")
    resim = ""
    if g.startswith("http"):
        g = html.escape(g, quote=True)
        resim = (f'<div class="pt-thumb"><img src="{g}" referrerpolicy="no-referrer" loading="lazy">'
                 f'<div class="buyuk"><img src="{g}" referrerpolicy="no-referrer" loading="lazy"></div></div>')
    return f'<div class="pt-urun" title="{ipucu}">{resim}<div><div class="nm">{ad}</div><div class="mt">{alt}</div></div></div>'


def _tsf_hucre(r: dict) -> str:
    tsf = r.get("tsf")
    notlar = "".join(f'<span class="tsf-alt">{html.escape(str(n))}</span>' for n in (r.get("tsf_notlari") or []))
    return f'<div><span class="tsf num">{_fmt(tsf) if tsf else "–"}</span>{notlar}</div>'


def fiyat_tablosu(h: dict, filtre: str = "Tümü", not_: str = "") -> None:
    satirlar = h["satirlar"]
    if filtre == "Sapmalar":
        satirlar = [r for r in satirlar if r["sapma"]]
    elif filtre == "Buybox kaybı":
        satirlar = [r for r in satirlar if r["bb_kayip"]]
    bas = ""
    for k in KANALLAR:
        logo = KANAL_LOGOLARI.get(k["ad"], "")
        if logo:
            logo = '<div style="height:22px;display:flex;align-items:center;margin-bottom:2px">' + logo + "</div>"
        bas += f'<div class="ch">{logo}<b>{html.escape(k["ad"])}</b><small>{k["tur"]}</small></div>'
    govde = "".join(
        f'<div class="pt-grid pt-row">{_urun_hucre(r)}{_tsf_hucre(r)}' + "".join(_hucre(c) for c in r["hucreler"]) + "</div>"
        for r in satirlar)
    st.markdown(
        f'<div class="pt-grid pt-thead"><span class="h">Ürün</span><span class="h">TSF</span>{bas}</div>{govde}'
        '<div class="pt-foot-note"><span><span class="bb own">BB</span> Buybox bizde</span>'
        '<span><span class="bb lost" style="color:#5F6B64">BB</span> Buybox başka satıcıda</span>'
        "<span>Fark oranı TSF'ye göre hesaplanır.</span>"
        + (f"<span>{html.escape(not_)}</span>" if not_ else "") + "</div>",
        unsafe_allow_html=True)
    return len(satirlar)


def yan_panel(h: dict) -> None:
    satirlar = ""
    for k in KANALLAR:
        a = h["kanal"][k["ad"]]; n = max(a["n"], 1)
        okp, wp = round(a["ok"] / n * 100), round(a["warn"] / n * 100)
        bp = max(0, 100 - okp - wp)
        alt = "Resmî mağaza · buybox yok" if k.get("resmi") else f'Buybox {a["bb_own"]} / {a["bb_n"]} listelemede bizde'
        satirlar += (f'<div class="pt-chrow"><div class="t">{html.escape(k["ad"])}<span class="num">%{okp} uyumlu</span></div>'
                     f'<div class="pt-bar" style="height:8px"><div style="width:{okp}%;background:#1F9D57"></div>'
                     f'<div style="width:{wp}%;background:#E0A800"></div><div style="width:{bp}%;background:#D2402F"></div></div>'
                     f'<small class="num">{alt}</small></div>')
    alarmlar = "".join(
        f'<div class="pt-alert"><div class="t">{html.escape(a["urun"])}<span class="num">−%{_pct(a["d"])}</span></div>'
        f'<small class="num">{html.escape(a["kanal"])} · {_fmt(a["fiyat"])} (TSF {_fmt(a["tsf"])})</small></div>'
        for a in h["alarmlar"][:4]) or '<small style="color:#6A7E72">Kritik sapma yok.</small>'
    st.markdown(
        f'<div class="pt-card pt-side"><h2>Kanal bazında uyum</h2>{satirlar}</div>'
        f'<div class="pt-card pt-side" style="margin-top:20px;border-color:#F0D2CC">'
        f'<div style="display:flex;justify-content:space-between;align-items:center"><h2>Öncelikli aksiyonlar</h2>'
        f'<span class="num" style="font-size:12px;font-weight:700;padding:3px 9px;border-radius:999px;background:#FDE6E2;color:#A3261A;white-space:nowrap">'
        f'{h["tot"]["bad"]} kritik</span></div>{alarmlar}</div>',
        unsafe_allow_html=True)


def alt_bant() -> None:
    kutular = ""
    for k in KANALLAR:
        logo = KANAL_LOGOLARI.get(k["ad"], "").replace('height="22"', 'height="38"')
        kutular += '<div class="pt-logo">' + (logo or html.escape(k["ad"])) + "</div>"
    st.markdown(
        '<div class="pt-footer"><div class="top"><span>Takip edilen satış kanalları</span>'
        '<span style="text-transform:none;letter-spacing:0;font-weight:500">Sağlık kategorisi · Fiyat &amp; Buybox Takibi</span></div>'
        f'<div class="pt-logos">{kutular}</div></div>',
        unsafe_allow_html=True)


# --------------------------------------------------------------------------
# Tek çağrıda tüm sayfa
# --------------------------------------------------------------------------
def dashboard(satirlar: list[dict], son_tarama: str = "", esik: float = 5, tablo_notu: str = "") -> None:
    ust_bant(son_tarama)
    baslik(esik)
    govde(satirlar, esik, tablo_notu)
    alt_bant()


def govde(satirlar: list[dict], esik: float = 5, tablo_notu: str = "") -> None:
    """[eklendi] Ust bant ve alt bant olmadan: KPI kartlari + fiyat tablosu + yan panel."""
    h = hesapla(satirlar, esik)
    kpi_kartlari(h, len(satirlar), esik)
    sol, sag = st.columns([3.2, 1], gap="medium")
    with sol:
        with st.container(border=True):
            a, b = st.columns([1.4, 1])
            with a:
                st.markdown('<div class="pt-table-head"><h2>Ürün bazlı fiyat görünümü</h2></div>', unsafe_allow_html=True)
            with b:
                secenekler = ["Tümü", "Sapmalar", "Buybox kaybı"]
                if hasattr(st, "segmented_control"):
                    filtre = st.segmented_control("Filtre", secenekler, default="Tümü",
                                                  label_visibility="collapsed", key="pt_filtre") or "Tümü"
                else:
                    filtre = st.radio("Filtre", secenekler, horizontal=True,
                                      label_visibility="collapsed", key="pt_filtre")
            fiyat_tablosu(h, filtre, tablo_notu)
    with sag:
        yan_panel(h)
